    private JSONObject preview;private LocalAuthorityEvidence.Loaded evidence;private String evidenceUri="",evidenceHash="",selectedBackup="",pendingName="",pendingBody="",importRequest="";private boolean busy;private int backupOffset,backupTotal;private android.window.OnBackInvokedCallback backCallback;
